import{_ as i,l as s,o as e,c as o,v as r,p as n,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"GRE 与隧道","description":"","frontmatter":{"title":"GRE 与隧道","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gre-tunnels.md","filePath":"cs/gre-tunnels.md","lastUpdated":1789023840000}'),P={name:"cs/gre-tunnels.md"};function c(h,a,R,_,G,u){const l=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="gre-与隧道" tabindex="-1">GRE 与隧道 <a class="header-anchor" href="#gre-与隧道" aria-label="Permalink to &quot;GRE 与隧道&quot;">​</a></h1><div class="epigraph"><p>GRE 把任意载荷装进另一张 IP 头，中间只转发外层；简单、无状态，校验、MTU 与安全都要另配。</p><footer>—— 据 RFC 2784 GRE；RFC 2890 密钥与序号；RFC 7676 IPv6 上的 GRE 整理</footer></div><p><a href="/cs/vxlan-overlay">VXLAN</a> 与 <a href="/cs/mpls">MPLS</a> 已是隧道。<a href="/cs/evpn">上一课</a> 是控制面。缺口是<strong>最简 IP 隧道</strong>：GRE、何时用、与 IPsec/NVGRE 对照。本课不把 IGMP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要把非 IP 或私网 IP 穿过只懂公网的核心：外层源/目的是隧道端点，内层原样。GRE 无内置拥塞与加密；序号可选。中间 ECMP 只看见外层五元组，熵不足则极化——VXLAN 用 UDP 源端口，GRE 常靠外层 IP 与 GRE 头。递归：隧道口的 MTU 必须小于底层，否则内层 PMTUD 黑洞（后课）。</p><p>不要把 GRE 当成 VXLAN 替代租户隔离：没有 VNI 标准语义，除非你自己编 key。</p><p><span class="marginnote">RFC 2784。PPTP 等历史用法不展开。IPsec 隧道模式是安全对照，不是 GRE 的升级补丁。</span></p><h3 id="无状态封装" tabindex="-1">无状态封装 <a class="header-anchor" href="#无状态封装" aria-label="Permalink to &quot;无状态封装&quot;">​</a></h3><p>中间只看外层 IP。无内置加密与 VNI 语义。Keepalive 是实现特性。递归 MTU 是黑洞温床。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：GRE / VXLAN / MPLS / IP-in-IP。画：内层包 → GRE → 外层 IP → 核心 LPM。与蜂窝 GTP 同类：锚点隧道。</p>',11)),(e(),n(E,null,{default:t(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INN%5B%22%E5%86%85%E5%B1%82%E6%8A%A5%E6%96%87%22%5D%20--%3E%20GRE%5B%22GRE%20%E5%A4%B4%22%5D%0A%20%20GRE%20--%3E%20OUT%5B%22%E5%A4%96%E5%B1%82%20IP%22%5D%0A%20%20OUT%20--%3E%20CORE%5B%22%E4%B8%AD%E9%97%B4%E5%8F%AA%E7%9C%8B%E5%A4%96%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OSPF 可在隧道上建邻接（小心递归与 MTU）。流量工程可把 GRE 当一条逻辑边，度量人工设。RSTP 不应把隧道当二层边除非你做了桥——那会把环带进核心。卫星链路上 GRE 只加头税，不减 RTT。</p><p>Keepalive 是实现特性，标准 GRE 无强制 Hello。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 WireGuard 的加密握手。多播 IGMP/PIM 是下一课。后课默认：GRE 是无状态封装；隔离与安全要另加。</p><p>把整个互联网当 GRE 网是 NAT 穿越的权宜，不是架构目标。</p><p>上一课留下的缺口在本课收口；「GRE 与隧道」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/multicast-igmp-pim">多播 IGMP / PIM</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GRE：外层 IP 转运，中间无内层状态。</li><li>熵与 MTU 是隧道共同税。</li><li>不提供 VPN 密钥语义或 VNI。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2784；RFC 2890。</li></ul>',10))])}const I=i(P,[["render",c]]);export{m as __pageData,I as default};
